import AppKit
import SwiftUI

/// Reveal's whole design-token system, in one file on purpose — colour, type,
/// and space, so there's exactly one place to go tweak the look for fun.
///
/// Three small, separate types (not one mega-struct) because colour/type/space
/// are genuinely different axes — but kept together here instead of scattered
/// across files, since the point of a token system is that you never reach for
/// a loose magic number: a colour is always a `Palette` case, a size always a
/// `Typo` step, a gap always a `Rhythm` step.
///
/// GENERATED by `packages/themes/scripts/build.js` (the `reveal` adapter) from
/// `packages/themes/<theme>/tokens.yaml` — edit the YAML, not this file; a hand
/// edit here is overwritten on the next regenerate. See `packages/themes/README.md`
/// ("The `scripts/` pipeline — multi-target theme codegen") for how to rebuild.

// MARK: - Palette (colour)

/// The Reveal palette — monochrome, plus one sacred accent.
///
/// A foreground ink and a background; every gray is an *opacity of the ink*, never
/// a separate hardcoded colour. No hue in the field where you judge a photo — the
/// chrome around it must not pull your eye off the image.
///
/// The one exception is `accent` — Leica red. It carries meaning (the active stage,
/// a kept frame, a critical gesture) and nothing else. Rare on purpose; never laid
/// over or beside the image being graded. Constant across light and dark.
struct Palette {
    let bg: Color
    let fg: Color
    /// A lifted surface — the ONE white for everything that floats above the canvas:
    /// the sidebar card, every floating panel, the popover, the status pill. (The top
    /// bar is deliberately *not* elevated — it's canvas, so the grid dissolves into it.)
    let elevated: Color
    /// The print-border every photo wears: white on light, neutral grey on dark.
    let photoFrame: Color
    private let accentOverride: Color?

    /// `bg`/`fg`/`accent` can be overridden per-call — a catalogue or story note's
    /// own Garden-style frontmatter tokens (`color-*`, resolved by `ThemeTokens`)
    /// layering over this base theme, exactly like a Garden note overrides its
    /// site's theme. `elevated`/`photoFrame` aren't part of that vocabulary (a
    /// photo-culling app needs a couple of extras a note theme doesn't) — they stay
    /// the base theme's values normally, and derive from an overridden `bg` (a
    /// light/dark nudge) only when one is actually supplied.
    init(_ scheme: ColorScheme, bg bgOverride: Color? = nil, fg fgOverride: Color? = nil,
         accent accentOverride: Color? = nil) {
        self.accentOverride = accentOverride
        if scheme == .dark {
            bg = bgOverride ?? Color(red: 0.1608, green: 0.1569, blue: 0.1529)
            fg = fgOverride ?? Color(red: 0.9686, green: 0.9647, blue: 0.9569)
            elevated = bgOverride.map { Self.adjustBrightness($0, by: 0.06) } ?? Color(red: 0.2118, green: 0.2078, blue: 0.2039)      // bg + ~6% — the floating chrome
            photoFrame = bgOverride.map { Self.adjustBrightness($0, by: -0.05) } ?? Color(red: 0.1529, green: 0.149, blue: 0.1451)     // a notch *darker* than bg — a quiet groove
        } else {
            bg = bgOverride ?? Color(red: 0.9686, green: 0.9647, blue: 0.9569)
            fg = fgOverride ?? Color(red: 0.1608, green: 0.1569, blue: 0.1529)
            elevated = bgOverride.map { Self.adjustBrightness($0, by: 0.06) } ?? Color(red: 1, green: 1, blue: 1)              // clean white cards over the grey well
            photoFrame = bgOverride.map { Self.adjustBrightness($0, by: -0.05) } ?? Color(red: 1, green: 1, blue: 1)
        }
    }

    /// HSB-brightness nudge (positive = lighten, negative = darken), clamped to
    /// [0, 1] — used only when `bg` is overridden, so `elevated`/`photoFrame`
    /// still relate to it sensibly instead of staying stuck on the base theme's.
    private static func adjustBrightness(_ color: Color, by amount: CGFloat) -> Color {
        let ns = NSColor(color).usingColorSpace(.deviceRGB) ?? .black
        var h: CGFloat = 0, s: CGFloat = 0, b: CGFloat = 0, a: CGFloat = 0
        ns.getHue(&h, saturation: &s, brightness: &b, alpha: &a)
        return Color(NSColor(hue: h, saturation: s, brightness: min(1, max(0, b + amount)), alpha: a))
    }

    var border:    Color { fg.opacity(0.14) }   // hairlines, panel edges
    var secondary: Color { fg.opacity(0.55) }   // dimmed text & glyphs
    var faint:     Color { fg.opacity(0.08) }   // idle thumbnail ring
    var selection: Color { fg }                 // the export set (solid ink)
    var cursor:    Color { fg.opacity(0.6) }    // keyboard cursor

    /// Leica red — the single accent: active state, kept frame, critical action.
    /// Same in both schemes (red reads identically on dark and on paper) —
    /// unless overridden, in which case the override carries to both too.
    var accent:      Color { accentOverride ?? Color(red: 0.1216, green: 0.3098, blue: 0.5098) }
    var accentFaint: Color { accent.opacity(0.12) }   // selected-row tint — never on the image
}

// MARK: - Typo (type)

/// Typography for Reveal — three roles, one scale.
///
/// A size always comes from the scale, never a loose magic number, and a face
/// is always one of the three roles, never picked ad hoc.
///
/// The three roles — like the markings on a camera:
///   • `din`  — DIN, uppercase, tracked. Technical labels: stage names, plugin
///              names, headers. The engravings on the top plate.
///   • `mono` — monospaced. Numbers that must align: ƒ, ISO, frame counts, dates.
///   • `text` — Inter. Anything you actually read in sentences.
///
/// The scale is a modular scale off one base, the way `Rhythm` steps off one unit.
enum Typo {
    /// The reading size — the base every step is measured from.
    static let base: CGFloat = 13
    /// The step ratio (a minor third). Every size is `base` × `ratio`ⁿ.
    static let ratio: CGFloat = 1.2

    static let micro: CGFloat = base / ratio / ratio  //  ≈ 9   — the finest marks: badges, tiny glyphs
    static let caption: CGFloat = base / ratio  // ≈ 10.8 — small spec labels, footers
    static let body: CGFloat = base  //   13   — reading + default labels
    static let title: CGFloat = base * ratio  // ≈ 15.6 — stage titles
    static let section: CGFloat = base * ratio * ratio  // ≈ 18.7 — section heads
    static let display: CGFloat = base * ratio * ratio * ratio  // ≈ 22.5 — the wordmark

    /// DIN — uppercase, tracked technical labels. Use with `.tracking(Typo.tracking(size))`.
    static func din(_ size: CGFloat = body) -> Font { .custom("DIN Condensed", size: size) }
    /// Monospaced readouts — numbers that align (SF Mono via the system face).
    static func mono(_ size: CGFloat = caption) -> Font {
        .system(size: size, weight: .regular, design: .monospaced)
    }
    /// Inter (bundled + registered at launch — see `main.swift`) — body text and
    /// default UI labels.
    static func text(_ size: CGFloat = body, weight: Font.Weight = .regular) -> Font {
        .custom("Inter", size: size).weight(weight)
    }

    /// Engraving-style letter-spacing for DIN caps (~0.12 em), derived from the size.
    static func tracking(_ size: CGFloat) -> CGFloat { size * 0.12 }
}

// MARK: - Rhythm (space)

/// Spacing & shape rhythm for the Reveal UI.
///
/// Mirrors the monorepo's `--space` scale: one baseline unit, everything a
/// multiple (or half) of it. The app breathes on the same grid as the rest of
/// Standard — every gap, inset, and radius comes from here, never a loose
/// magic number.
enum Rhythm {
    /// The baseline unit. All spacing is a step off this (a 4-pt grid).
    static let unit: CGFloat = 8

    static let xxs: CGFloat = unit * 0.25  //  2 — the tightest gap (star rows, fine insets)
    static let xs:  CGFloat = unit * 0.5   //  4 — hairline insets, tight chrome
    static let sm:  CGFloat = unit         //  8 — default small gap
    static let md:  CGFloat = unit * 1.5   // 12 — control padding
    static let lg:  CGFloat = unit * 2     // 16 — grid gutter, bar insets
    static let xl:  CGFloat = unit * 3     // 24 — section padding
    static let xxl: CGFloat = unit * 4     // 32 — generous frame margins

    /// Shape — radii read off the same unit (cf. `--radius`/`--leading`).
    static let radius:      CGFloat = unit * 1.5   // 12 — bars, panels, loupe
    static let radiusSmall: CGFloat = unit * 0.75  //  6 — thumbnails, rows
    static let hairline:    CGFloat = 1

    /// A comfortable reading measure — ~66 characters, the classic print/web
    /// line-length target (~42rem at the usual 16px/1rem). The story compose
    /// column centres to this instead of stretching edge-to-edge.
    static let readingWidth: CGFloat = 672
}
